new #[Layout('app::v2.layouts.app')] class extends Component {
    use WithPagination;
    #[Url(as: 'q', keep: true)] public string $search = '';
    #[Url(keep: true)] public string $product = 'all';
    #[Url(keep: true)] public string $type = 'all';
    #[Url(keep: true)] public string $sort = 'newest';
    #[Url(as: 'folder', except: '')] public string $folder = '';
    protected $paginationTheme = 'bootstrap';
    public int $perPage = 12;
    public array $selectedIds = [], $unavailableIds = [];
    public ?int $selectedFileId = null;
    public ?string $selectedPreviewUrl = null, $selectedPreviewKind = null, $selectedPreviewName = null, $selectedPreviewMime = null;
    public bool $showDeleteConfirmation = false;

    public function updatedSearch(): void { $this->filtersChanged(); }
    public function updatedProduct(): void { $this->filtersChanged(); }
    public function updatedType(): void { $this->filtersChanged(); }
    public function updatedSort(): void { $this->filtersChanged(); }
    public function filtersChanged(): void { $this->selectedIds=[]; $this->clearPreview(); unset($this->files, $this->selectedFile, $this->selectedLibrary); $this->resetPage('storagePage'); }
    public function openFolder(string $folder): void { $this->folder=$folder; $this->filtersChanged(); }
    public function closeFolder(): void { $this->folder=''; $this->filtersChanged(); $this->redirect($this->rootUrl, navigate:true); }
    #[Computed] public function rootUrl(): string { return url(app()->getLocale().'/app-v2/storage').'?'.http_build_query(['q'=>$this->search,'product'=>$this->product,'type'=>$this->type,'sort'=>$this->sort]); }
    #[Computed] public function folderLabel(): string {
        $file = $this->storageFiles->first(fn ($file) => $this->folderKey($file) === $this->folder);
        if (! $file) return __('Folder');
        $jobId = (string) (data_get($file->meta,'job_id') ?: $file->source_id);
        $job = MlJob::where('customer_id', auth('app')->id())->find($jobId, ['id','input','model_key']);
        return $this->readableFolderName($file, $job);
    }
    protected function readableFolderName(CustomerFile $file, ?MlJob $job): string {
        $label = data_get($job?->input, 'file_name') ?: data_get($job?->input, 'audio_name') ?: data_get($job?->input, 'text') ?: data_get($job?->input, 'segments.0.text') ?: data_get($file->meta, 'original_name');
        return Str::limit(trim((string) ($label ?: app(CustomerStorageLibrary::class)->identity($file,$job)['title'].' · '.$file->created_at?->format('d M Y, H:i'))), 90);
    }
    #[Computed] public function storageFiles() { return app(CustomerStorageLibrary::class)->filesFor((int)auth('app')->id())->get(); }
    public function clearSelection(): void { $this->selectedIds=[]; }
    public function clearPreview(): void { $this->selectedFileId=null; $this->selectedPreviewUrl=$this->selectedPreviewKind=$this->selectedPreviewName=$this->selectedPreviewMime=null; }

    #[Computed] public function usage(): array {
        $customer=auth('app')->user(); $state=$customer?->storageQuotaState()??[];
        $used=max(0,(int)($state['used_bytes']??CustomerUsage::query()->where('customer_id',(int)$customer?->id)->value('storage_used_bytes')??0)); $limit=max(1,(int)($state['current_limit_bytes']??512*1024*1024));
        return ['used'=>$used,'limit'=>$limit,'available'=>max(0,$limit-$used),'percent'=>min(100,(int)round($used/$limit*100)),'count'=>$this->storageFiles->count()];
    }
    #[Computed] public function libraryNavigation(): array { $customer=auth('app')->user(); return $customer?app(CustomerStorageLibrary::class)->navigation($customer):[]; }
    #[Computed] public function selectedLibrary(): ?array { foreach($this->libraryNavigation as $service) foreach($service['products'] as $product) if($product['key']===$this->product)return $product; return null; }
    #[Computed] public function destructiveOperationsAllowed(): bool { return app(StorageFileDeletionService::class)->destructiveOperationsAllowed(); }
    #[Computed] public function selectedFile(): ?array {if(!$this->selectedFileId)return null;$file=$this->ownedFile($this->selectedFileId);if(!$file)return null;$jobId=(string)(data_get($file->meta,'job_id')?:$file->source_id);$job=MlJob::query()->where('customer_id',(int)$file->customer_id)->find($jobId);return $this->presentFile($file,$job);}
    #[Computed] public function overview(): array {
        $groups=['audio'=>['label'=>__('Audio'),'icon'=>'ri-volume-up-line','count'=>0,'size'=>0],'documents'=>['label'=>__('Documents'),'icon'=>'ri-file-text-line','count'=>0,'size'=>0],'archives'=>['label'=>__('Archives'),'icon'=>'ri-file-zip-line','count'=>0,'size'=>0]];
        $this->storageFiles->each(function($file)use(&$groups){$ext=strtolower(pathinfo((string)$file->path,PATHINFO_EXTENSION));$key=str_starts_with((string)$file->mime,'audio/')||in_array($ext,['mp3','wav','flac','m4a','aac','ogg','opus'],true)?'audio':($ext==='zip'?'archives':'documents');$groups[$key]['count']++;$groups[$key]['size']+=max(0,(int)$file->size_bytes);}); return $groups;
    }
    #[Computed] public function files(): LengthAwarePaginator {
        $customer=auth('app')->user(); abort_unless($customer,403); $q=app(CustomerStorageLibrary::class)->filesFor((int)$customer->id);
        $this->applyProductFilter($q,$customer); $this->applyTypeFilter($q);
        if(trim($this->search)!==''){ $term=trim($this->search); $jobIds=MlJob::query()->where('customer_id',(int)$customer->id)->where(fn($j)=>$j->where('input','like','%'.$term.'%')->orWhere('output','like','%'.$term.'%'))->pluck('id')->map(fn($id)=>(string)$id)->all(); $q->where(function($f)use($term,$jobIds){$f->where('path','like','%'.$term.'%')->orWhere('tool_code','like','%'.$term.'%')->orWhere('source_id','like','%'.$term.'%')->orWhere('meta','like','%'.$term.'%');if($jobIds!==[]){$f->orWhereIn('source_id',$jobIds);foreach($jobIds as $jobId)$f->orWhere('meta','like','%'.$jobId.'%');}}); }
        $all=$q->get(); if($this->folder==='') return $this->folderPaginator($all,$customer); $all=$all->filter(fn($file)=>$this->folderKey($file)===$this->folder); match($this->sort){'oldest'=>$all=$all->sortBy('created_at'),'largest'=>$all=$all->sortByDesc('size_bytes'),'smallest'=>$all=$all->sortBy('size_bytes'),'name'=>$all=$all->sortBy('path'),default=>$all=$all->sortByDesc('created_at')}; $files=$this->paginate($all,$this->perPage);
        $ids=$files->getCollection()->map(fn($f)=>(string)(data_get($f->meta,'job_id')?:$f->source_id))->filter()->unique();$jobs=MlJob::query()->where('customer_id',(int)$customer->id)->whereIn('id',$ids)->get(['id','input','model_key'])->keyBy('id');$files->setCollection($files->getCollection()->map(fn($f)=>$this->presentFile($f,$jobs->get((string)(data_get($f->meta,'job_id')?:$f->source_id)))));return $files;
    }
    protected function folderPaginator($files,$customer):LengthAwarePaginator{$ids=$files->map(fn($f)=>(string)(data_get($f->meta,'job_id')?:$f->source_id))->filter()->unique();$jobs=MlJob::query()->where('customer_id',(int)$customer->id)->whereIn('id',$ids)->get(['id','input','model_key'])->keyBy('id');$groups=$files->groupBy(fn($f)=>$this->folderKey($f))->map(function($items,$key)use($jobs){$first=$items->first();$jobId=(string)(data_get($first->meta,'job_id')?:$first->source_id);$library=app(CustomerStorageLibrary::class)->identity($first,$jobs->get($jobId));return ['retention'=>app(CustomerStorageLibrary::class)->retention($first),'folder'=>true,'folder_key'=>$key,'id'=>'folder-'.$key,'name'=>$this->readableFolderName($first,$jobs->get($jobId)),'text'=>trans_choice(':count files',$items->count(),['count'=>$items->count()]),'library'=>$library,'type'=>__('Folder'),'extension'=>'JOB','size'=>$this->formatBytes((int)$items->sum('size_bytes')),'size_bytes'=>(int)$items->sum('size_bytes'),'when'=>$items->max('created_at')?->diffForHumans()??'','created'=>$items->max('created_at')?->format('d M Y, h:i A')??'','timestamp'=>$items->max('created_at')?->getTimestamp()??0,'unavailable'=>false,'previewable'=>false,'audio'=>false];});$groups=match($this->sort){'oldest'=>$groups->sortBy('timestamp'),'largest'=>$groups->sortByDesc('size_bytes'),'smallest'=>$groups->sortBy('size_bytes'),'name'=>$groups->sortBy('name'),default=>$groups->sortByDesc('timestamp')};return $this->paginate($groups->values(),$this->perPage);}
    protected function paginate($items,int $perPage):LengthAwarePaginator{$page=$this->getPage('storagePage');return new LengthAwarePaginator($items->forPage($page,$perPage)->values(),$items->count(),$perPage,$page,['path'=>request()->url(),'pageName'=>'storagePage']);}
    protected function folderKey(CustomerFile $file):string{$job=(string)(data_get($file->meta,'job_id')?:data_get($file->meta,'queue_id')?:data_get($file->meta,'request_id')?:data_get($file->meta,'task_id')?:$file->source_id);if($job!=='')return 'job:'.$job;$parts=explode('/',trim((string)$file->path,'/'));$tool=array_search((string)$file->tool_code,$parts,true);return $tool!==false&&isset($parts[$tool+1])?'path:'.$parts[$tool].'/'.$parts[$tool+1]:'file:'.$file->id;}
    public function togglePageSelection(bool $selected): void {$ids=collect($this->files->items())->reject(fn($item)=>$item['folder']??false)->pluck('id')->map(fn($id)=>(int)$id)->all();$this->selectedIds=$selected?array_values(array_unique(array_merge($this->selectedIds,$ids))):array_values(array_diff($this->selectedIds,$ids));}
    public function selectFile(int $id): void {$file=$this->ownedFile($id);if(!$file)return;$this->clearPreview();$this->selectedFileId=$id;$preview=$this->isPreviewable($file)?$file:$this->sourceAudioFor($file);if(!$preview)return;$url=app(CustomerOutputStorage::class)->temporaryUrlForCustomerFile($preview,'inline');if($url===null){if((int)$preview->id===(int)$file->id)$this->markUnavailable($id);else $this->dispatch('alert',type:'warning',message:__('The source audio is no longer available in storage.'));return;}$this->selectedPreviewUrl=$url;$this->selectedPreviewKind=(int)$preview->id!==$id?'source':$this->previewKind($preview);$this->selectedPreviewName=basename((string)$preview->path);$this->selectedPreviewMime=(string)$preview->mime;}
    public function requestBulkDownload(){return $this->selectedIds===[]?null:$this->redirectRoute('app.v2.storage.bulk-download',['locale'=>app()->getLocale(),'files'=>array_values(array_map('intval',$this->selectedIds))],navigate:false);}
    public function confirmBulkDelete(): void {if($this->selectedIds!==[]&&$this->destructiveOperationsAllowed)$this->showDeleteConfirmation=true;}
    public function confirmDeleteFile(int $id): void {if($this->ownedFile($id)&&$this->destructiveOperationsAllowed){$this->selectedIds=[$id];$this->showDeleteConfirmation=true;}}
    public function deleteSelected(): void { $customer=auth('app')->user();if(!$customer||$this->selectedIds===[])return;try{$r=app(StorageFileDeletionService::class)->deleteOwned($customer,$this->selectedIds);$this->selectedIds=[];$this->clearPreview();\App\Support\AppShellData::forgetForCurrentCustomer();$this->dispatch('header:refresh');$message=__('Selected files deleted.');if($r['missing']>0)$message.=' '.__(':count selected files were already missing from storage and were cleaned up.',['count'=>$r['missing']]);if($r['failed']>0||$r['skipped']>0)$message.=' '.__('Some selected files could not be deleted.');$this->dispatch('alert',type:$r['failed']>0?'warning':'success',message:$message);}catch(StorageDestructiveOperationBlocked){$this->dispatch('alert',type:'warning',message:__('Storage actions are disabled in this environment.'));}finally{$this->showDeleteConfirmation=false;$this->resetPage('storagePage');}}
    protected function applyProductFilter($q,$customer): void {$scopes=['harakat-1'=>['harakat'],'zeta-1'=>['zeta'],'theta-1'=>['theta'],'apollo-legacy'=>['tts','xtts'],'delta'=>['ftts'],'vector-legacy'=>['clone_tts','clone-tts','clone_xtts'],'wasr'=>['wasr','asr'],'qasr'=>['qasr'],'leo'=>['leo'],'caption'=>['caption'],'translation'=>['tran'],'ocr'=>['ocr'],'stem'=>['stem']];$services=['text-to-speech'=>['zeta','xomni','xomni-v2','tts','xtts','ftts'],'clone-text-to-speech'=>['theta','clone_xomni','vector-v2','clone_tts','clone-tts','clone_xtts'],'speech-to-text'=>['wasr','qasr','leo','asr','caption','tran'],'ocr'=>['ocr','harakat'],'stem'=>['stem']];if(str_starts_with($this->product,'service:')){$s=substr($this->product,8);if(isset($services[$s]))$q->whereIn('tool_code',$services[$s]);return;}if(isset($scopes[$this->product])){$q->whereIn('tool_code',$scopes[$this->product]);return;}if(!in_array($this->product,['apollo-1','apollo-2','vector-1','vector-2'],true))return;$tools=str_starts_with($this->product,'apollo')?(str_ends_with($this->product,'-2')?['xomni','xomni-v2']:['xomni']):(str_ends_with($this->product,'-2')?['clone_xomni','vector-v2']:['clone_xomni']);$modelTwo=MlJob::query()->where('customer_id',(int)$customer->id)->where('model_key','model_2')->pluck('id')->map(fn($id)=>(string)$id)->all();$wantTwo=str_ends_with($this->product,'-2');$ids=CustomerFile::query()->where('customer_id',(int)$customer->id)->where('status','active')->whereIn('tool_code',$tools)->get(['id','tool_code','source_id','meta'])->filter(function($file)use($modelTwo,$wantTwo){if(in_array((string)$file->tool_code,['xomni-v2','vector-v2'],true))return $wantTwo;$jobId=(string)(data_get($file->meta,'job_id')?:$file->source_id);$isTwo=(string)data_get($file->meta,'model_key')==='model_2'||in_array($jobId,$modelTwo,true);return $wantTwo?$isTwo:!$isTwo;})->pluck('id');$q->whereIn('id',$ids);}
    protected function applyTypeFilter($q): void {$patterns=match($this->type){'audio'=>['audio/%','%.mp3','%.wav','%.flac','%.m4a'],'text'=>['text/%','%.txt','%.srt','%.vtt'],'document'=>['application/pdf%','%.pdf','%.doc','%.docx'],'archive'=>['application/zip%','%.zip'],default=>[]};if($patterns!==[])$q->where(function($f)use($patterns){foreach($patterns as $p)str_contains($p,'/')?$f->orWhere('mime','like',$p):$f->orWhere('path','like',$p);});}
    protected function presentFile(CustomerFile $file,?MlJob $job):array{$meta=(array)$file->meta;$ext=strtolower(pathinfo((string)$file->path,PATHINFO_EXTENSION));return ['retention'=>app(CustomerStorageLibrary::class)->retention($file),'id'=>(int)$file->id,'name'=>(string)(data_get($meta,'original_name')?:basename((string)$file->path)),'library'=>app(CustomerStorageLibrary::class)->identity($file,$job),'type'=>$this->typeLabel((string)$file->mime,$ext),'extension'=>$ext!==''?strtoupper($ext):__('File'),'text'=>Str::limit((string)data_get($job?->input,'text',data_get($meta,'text','')),120),'size'=>$this->formatBytes((int)$file->size_bytes),'when'=>$file->created_at?->diffForHumans()??'','created'=>$file->created_at?->format('d M Y, h:i A')??'','audio'=>$this->isAudio($file),'previewable'=>$this->isPreviewable($file)||$this->sourceAudioFor($file)!==null,'unavailable'=>in_array((int)$file->id,$this->unavailableIds,true),'download_url'=>route('app.v2.storage.download',['locale'=>app()->getLocale(),'file'=>$file->id])];}
    protected function ownedFile(int $id):?CustomerFile{return app(CustomerStorageLibrary::class)->filesFor((int)auth('app')->id())->find($id);} protected function markUnavailable(int $id):void{$this->unavailableIds=array_values(array_unique([...$this->unavailableIds,$id]));$this->selectedPreviewUrl=$this->selectedPreviewKind=$this->selectedPreviewName=$this->selectedPreviewMime=null;$this->dispatch('alert',type:'warning',message:__('This file is no longer available in storage.'));}
    protected function sourceAudioFor(CustomerFile $file):?CustomerFile{if(!in_array((string)$file->tool_code,['wasr','qasr','leo','asr','caption'],true))return null;$jobId=(string)(data_get($file->meta,'job_id')?:($file->source_type==='ml_job'?$file->source_id:''));return $jobId===''?null:$this->storageFiles->where('purpose','input_audio')->where('tool_code',(string)$file->tool_code)->first(fn($f)=>(string)(data_get($f->meta,'job_id')?:$f->source_id)===$jobId&&$this->isAudio($f));}
    protected function isAudio(CustomerFile $f):bool{return str_starts_with((string)$f->mime,'audio/')||in_array(strtolower(pathinfo((string)$f->path,PATHINFO_EXTENSION)),['mp3','wav','flac','m4a','aac','ogg','opus'],true);}protected function isPreviewable(CustomerFile $f):bool{return $this->isAudio($f)||str_starts_with((string)$f->mime,'image/')||str_starts_with((string)$f->mime,'video/');}protected function previewKind(CustomerFile $f):string{return $this->isAudio($f)?'audio':(str_starts_with((string)$f->mime,'image/')?'image':'video');}protected function typeLabel(string $mime,string $e):string{return str_starts_with($mime,'audio/')?__('Audio'):(str_starts_with($mime,'image/')?__('Image'):(str_starts_with($mime,'video/')?__('Video'):(in_array($e,['srt','vtt'],true)?__('Subtitles'):(in_array($e,['txt','md','json'],true)?__('Text'):(in_array($e,['pdf','doc','docx'],true)?__('Document'):($e==='zip'?__('Archive'):__('Other')))))));}protected function formatBytes(int $b):string{foreach(['B','KB','MB','GB']as$i=>$u)if($b<1024**($i+1)||$i===3)return number_format($b/(1024**$i),$i===0?0:1).' '.$u;return'0 B';}
};
